// Sample team logos — the fictional Northgate Bulldogs. The app opens with the
// first one loaded (labelled "Sample logo"). Artwork is generated by
// scripts/gen-samples.mjs (every shape is a plain <path>: no fonts, no
// external refs), so each file renders the same as <img>, in canvas and in
// every effect. bulldog-on-white.jpg is a background-removal test fixture and
// is deliberately not listed here.
import bulldogUrl from "./bulldog.svg?url";
import crestUrl from "./crest.svg?url";
import monogramUrl from "./monogram.svg?url";

const team = { school: "Northgate", mascot: "Bulldogs" };
const palette = {
  primary: "#13294B", // navy
  secondary: "#F2A900", // athletic gold
  accent: "#FFFFFF",
  dark: "#0B0D10",
  light: "#F4F5F7",
};

export const SAMPLE_LOGOS = [
  {
    id: "bulldog",
    name: "Bulldog head",
    blurb: "Full-color mascot head with spiked collar",
    url: bulldogUrl,
    team: { ...team },
    palette: { ...palette },
  },
  {
    id: "crest",
    name: "Round crest",
    blurb: "Badge with arched lettering and the mascot",
    url: crestUrl,
    team: { ...team },
    palette: { ...palette },
  },
  {
    id: "monogram",
    name: "Varsity N",
    blurb: "Tackle-twill block letter, three outlines",
    url: monogramUrl,
    team: { ...team },
    palette: { ...palette },
  },
];

export const DEFAULT_SAMPLE = SAMPLE_LOGOS[0];

export function getSample(id) {
  return SAMPLE_LOGOS.find((s) => s.id === id) || null;
}
